/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_consumo_materiales` AFTER INSERT ON `hechos_produccion` FOR EACH ROW BEGIN
    INSERT INTO hechos_consumo_materiales (corrida_id, material_id, unidad, consumo)
    SELECT NEW.corrida_id, r.material_id, r.unidad,
           (NEW.aprobadas + NEW.rechazadas) * r.cantidad_por_barra
    FROM vw_receta r
    WHERE r.producto_id = NEW.producto_id
    ON DUPLICATE KEY UPDATE consumo = consumo + VALUES(consumo);
END */;;
