--
/*!50003 DROP PROCEDURE IF EXISTS `sp_cargar_corrida` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cargar_corrida`()
BEGIN
    DECLARE v_anio    INT;
    DECLARE v_corrida INT;
    DECLARE v_dia_max INT;

    IF (SELECT COUNT(*) FROM tmp_corrida) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'tmp_corrida esta vacia: FlexSim aun no exporto la corrida';
    END IF;

    SELECT COALESCE(MAX(COALESCE(anio_fin, anio_simulado)), 2026) + 1 INTO v_anio FROM corridas;

    -- Corrida (el trigger confirma anio/fecha_id si vienen NULL)
    INSERT INTO corridas (fecha_id, anio_simulado, duracion_minutos, descripcion)
    SELECT v_anio * 10000 + 101, v_anio, tiempo_total, descripcion
    FROM tmp_corrida ORDER BY id DESC LIMIT 1;

    SET v_corrida = LAST_INSERT_ID();

    -- Rendimiento por maquina
    INSERT IGNORE INTO hechos_rendimiento (corrida_id, maquina_id, unidades_salida)
    SELECT v_corrida, m.maquina_id, t.unidades_salida
    FROM tmp_datos t
    JOIN maquinas m ON m.objeto = t.objeto;

    -- Produccion por formula (dispara el trigger de consumo de materiales)
    INSERT IGNORE INTO hechos_produccion (corrida_id, producto_id, aprobadas, rechazadas)
    SELECT v_corrida, p.producto_id, t.aprobadas, t.rechazadas
    FROM tmp_produccion t
    JOIN productos p ON p.formula = t.formula;

    -- Produccion diaria: dia ordinal -> fecha real
    --   dia 1   -> 1-Ene del anio de inicio
    --   dia 366 -> 1-Ene del anio siguiente (2028 si inicio en 2027)
    --   dia 731 -> 1-Ene del tercer anio
    INSERT INTO hechos_diaria_productos (corrida_id, fecha_id, producto_id, aprobadas, rechazadas)
    SELECT v_corrida,
           CAST(DATE_FORMAT(MAKEDATE(v_anio, t.dia), '%Y%m%d') AS UNSIGNED),
           p.producto_id,
           SUM(t.aprobadas), SUM(t.rechazadas)
    FROM (
        SELECT dia, Champu_Coco    AS aprobadas, Coco_Rech     AS rechazadas, 'Champu_Coco'     AS formula FROM tmp_por_dia_prod
        UNION ALL SELECT dia, Champu_Romero,  Romero_Rech,   'Champu_Romero'  FROM tmp_por_dia_prod
        UNION ALL SELECT dia, Champu_Mango,   Mango_Rech,    'Champu_Mango'   FROM tmp_por_dia_prod
        UNION ALL SELECT dia, Acond_CocoSilk, CocoSilk_Rech, 'Acond_CocoSilk' FROM tmp_por_dia_prod
        UNION ALL SELECT dia, Acond_Romero,   RomeroA_Rech,  'Acond_Romero'   FROM tmp_por_dia_prod
        UNION ALL SELECT dia, Acond_Mango,    MangoA_Rech,   'Acond_Mango'    FROM tmp_por_dia_prod
    ) t
    JOIN productos p ON p.formula = t.formula
    GROUP BY t.dia, p.producto_id
    ON DUPLICATE KEY UPDATE
        aprobadas  = aprobadas  + VALUES(aprobadas),
        rechazadas = rechazadas + VALUES(rechazadas);

    -- Registrar en que ano TERMINA la corrida (3 anos -> anio_fin = inicio + 2)
    SELECT MAX(dia) INTO v_dia_max FROM tmp_por_dia_prod;
    UPDATE corridas
    SET anio_fin = YEAR(MAKEDATE(v_anio, IFNULL(v_dia_max, 1)))
    WHERE corrida_id = v_corrida AND anio_fin IS NULL;

    -- Vaciar staging para la siguiente corrida
    TRUNCATE TABLE tmp_corrida;
    TRUNCATE TABLE tmp_datos;
    TRUNCATE TABLE tmp_produccion;
    TRUNCATE TABLE tmp_por_dia_prod;

    SELECT v_corrida AS corrida_cargada,
           v_anio    AS anio_inicio,
           (SELECT anio_fin FROM corridas WHERE corrida_id = v_corrida) AS anio_fin;
END ;;
DELIMITER ;
